package br.com.archlab.simulation.core.v3;
import org.junit.jupiter.api.Test;import org.junit.jupiter.params.ParameterizedTest;import org.junit.jupiter.params.provider.EnumSource;
import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static br.com.archlab.simulation.core.v3.ArchitectureV3.*;import static br.com.archlab.simulation.core.v3.ExecutionPlanV3.*;
import br.com.archlab.simulation.core.v3.ExecutionPlanV3.Process;
class AsynchronousExecutionV3Test {
    static IdentifierV3 id(String x){return new IdentifierV3(x);}static PropertyValueV3.IntegerValue n(long x){return new PropertyValueV3.IntegerValue(x);}static Map<Outcome,IdentifierV3> next(Outcome o,String s){return Map.of(o,id(s));}
    static SimulationRequestV3 groups(JoinPolicy policy,RemainingPolicy remaining,Integer quorum,Long deadline,long... durations){
        var original=SynchronousExecutionV3Test.fixture(null,null,false,true);var steps=new ArrayList<Step>();var branches=new ArrayList<Branch>();var required=new ArrayList<IdentifierV3>();
        for(int i=0;i<durations.length;i++){String branch="b"+i,entry="d"+i,end="e"+i;branches.add(new Branch(id(branch),id(entry)));required.add(id(branch));steps.add(new Delay(id(entry),new DurationMsV3(Math.abs(durations[i])),id(end)));steps.add(durations[i]<0?new Fail(id(end),Scope.BRANCH,id("branch-error")):new Complete(id(end),Scope.BRANCH,id("branch-ok")));}
        steps.add(new Fork(id("fork"),branches,id("join")));steps.add(new Join(id("join"),policy,required,quorum,remaining,deadline==null?null:new DurationMsV3(deadline),Map.of(Outcome.SATISFIED,id("done"),Outcome.UNSATISFIABLE,id("fail"),Outcome.TIMEOUT,id("fail"))));steps.add(new Complete(id("done"),Scope.ACTIVATION,id("ok")));steps.add(new Fail(id("fail"),Scope.ACTIVATION,id("error")));
        var plan=new ExecutionPlanV3(id("api-plan"),id("api-op"),id("fork"),new Limits(1000,100),steps);var a=original.architecture();var relations=new ArrayList<>(a.relations());var r=(Communication)relations.getFirst();relations.set(0,new Communication(r.id(),r.sourceEndpointId(),r.targetEndpointId(),r.protocolProfileId(),Map.of("latencyMs",n(0))));
        var architecture=new ArchitectureV3(a.id(),a.schemaVersion(),a.components(),a.resources(),a.endpoints(),a.operations(),relations,List.of(plan));return new SimulationRequestV3(architecture,original.scenario(),original.options());
    }
    static SimulationRequestV3 reference(AwaitPublish await,Map<String,PropertyValueV3> queueProperties){
        var original=SynchronousExecutionV3Test.fixture(null,null,false,true);var a=original.architecture();var components=new ArrayList<>(a.components());components.set(2,new Component(id("db"),id("DATABASE_GENERIC"),"DB",Map.of("processingMs",n(40))));components.add(new Component(id("broker"),id("BROKER_GENERIC"),"Broker",Map.of()));components.add(new Component(id("queue"),id("QUEUE_GENERIC"),"Queue",Map.of()));components.add(new Component(id("telemetry"),id("TELEMETRY_GENERIC"),"Telemetry",Map.of("processingMs",n(90))));
        var props=new LinkedHashMap<String,PropertyValueV3>();props.put("capacity",n(10));props.put("consumerEndpointId",new PropertyValueV3.Reference(id("telemetry-in"),id("ENDPOINT")));props.putAll(queueProperties);
        var resources=new ArrayList<>(a.resources());resources.add(new Resource(id("topic"),id("TOPIC"),id("broker"),Map.of("queueIds",new PropertyValueV3.Values(List.of(new PropertyValueV3.Reference(id("messages"),id("MESSAGE_QUEUE")))))));resources.add(new Resource(id("messages"),id("MESSAGE_QUEUE"),id("queue"),props));resources.add(new Resource(id("telemetry-pool"),id("PROCESSING_POOL"),id("telemetry"),Map.of("capacity",n(1))));
        var endpoints=new ArrayList<>(a.endpoints());endpoints.add(new Endpoint(id("telemetry-in"),id("telemetry"),Direction.INBOUND,id("TELEMETRY"),List.of(id("collect")),Map.of()));var operations=new ArrayList<>(a.operations());operations.add(new Operation(id("collect"),id("telemetry"),"Collect",null,null,new Binding(BindingKind.NATIVE_BEHAVIOR,id("TELEMETRY_COLLECT")),List.of()));
        var relations=new ArrayList<Relation>();for(var value:a.relations()){var r=(Communication)value;relations.add(new Communication(r.id(),r.sourceEndpointId(),r.targetEndpointId(),r.protocolProfileId(),Map.of("latencyMs",n(r.id().equals(id("client-api"))?0:10))));}
        var transitions=new EnumMap<Outcome,IdentifierV3>(Outcome.class);transitions.put(await==AwaitPublish.NONE?Outcome.DISPATCHED:await==AwaitPublish.BROKER_ACK?Outcome.ACCEPTED:Outcome.SUCCESS,id("done"));transitions.put(Outcome.FAILURE,id("fail"));if(await!=AwaitPublish.NONE){transitions.put(Outcome.TIMEOUT,id("fail"));transitions.put(Outcome.REJECTED,id("fail"));}
        var plan=new ExecutionPlanV3(id("api-plan"),id("api-op"),id("pre"),new Limits(100,10),List.of(new Process(id("pre"),new DurationMsV3(20),null,next(Outcome.NEXT,"call")),new Call(id("call"),id("api-db"),id("db-op"),AwaitCall.RESPONSE,null,Map.of(Outcome.SUCCESS,id("post"),Outcome.FAILURE,id("fail"))),new Process(id("post"),new DurationMsV3(40),null,next(Outcome.NEXT,"publish")),new Publish(id("publish"),id("topic"),null,await,null,transitions),new Complete(id("done"),Scope.ACTIVATION,id("ok")),new Fail(id("fail"),Scope.ACTIVATION,id("error"))));
        return new SimulationRequestV3(new ArchitectureV3(a.id(),a.schemaVersion(),components,resources,endpoints,operations,relations,List.of(plan)),original.scenario(),original.options());
    }
    @Test void referenceUsesAllSixComponentsAndSeparates120MsFrom210Ms(){var request=reference(AwaitPublish.NONE,Map.of());var validation=new ArchitectureValidatorV3(TypeCatalogV3.initial()).validate(request.architecture());assertTrue(validation.valid(),validation.toString());assertTrue(new ExecutionPlanValidatorV3(TypeCatalogV3.initial()).validate(request.architecture(),request.architecture().executionPlans().getFirst()).valid());var engine=new SimulationEngineV3(request);engine.run();assertEquals(120L,engine.control().principalResponseAt());assertEquals(210,engine.checkpoint().current().agenda().nowMs());assertEquals("COMPLETED",engine.control().globalStop());assertEquals(90L,engine.control().processing().get(id("telemetry")));assertTrue(engine.checkpoint().current().state().entities().values().stream().anyMatch(e->e instanceof RuntimeEntityV3.QueueEntry q && q.status()==RuntimeEntityV3.QueueEntryStatus.ACKNOWLEDGED));}
    @ParameterizedTest @EnumSource(AwaitPublish.class) void supportsEveryPublicationAwaitMode(AwaitPublish await){var engine=new SimulationEngineV3(reference(await,Map.of()));engine.run();assertEquals(await==AwaitPublish.CONSUMER_ACK?210L:120L,engine.control().principalResponseAt());assertEquals(210,engine.checkpoint().current().agenda().nowMs());assertEquals("COMPLETED",engine.control().globalStop());}
    @Test void allJoinWaitsForBothAndAnyKeepsBackgroundBranches(){var all=new SimulationEngineV3(groups(JoinPolicy.ALL,RemainingPolicy.CONTINUE,null,null,30,80));all.run();assertEquals(80L,all.control().principalResponseAt());var any=new SimulationEngineV3(groups(JoinPolicy.ANY,RemainingPolicy.CONTINUE,null,null,30,80));any.run();assertEquals(30L,any.control().principalResponseAt());assertEquals(80,any.checkpoint().current().agenda().nowMs());}
    @Test void quorumCanContinueOrCancelRemainingWork(){var continued=new SimulationEngineV3(groups(JoinPolicy.QUORUM,RemainingPolicy.CONTINUE,2,null,10,20,70));continued.run();assertEquals(20L,continued.control().principalResponseAt());assertEquals(70,continued.checkpoint().current().agenda().nowMs());var cancelled=new SimulationEngineV3(groups(JoinPolicy.QUORUM,RemainingPolicy.CANCEL_REQUEST,2,null,10,20,70));cancelled.run();assertEquals(20L,cancelled.control().principalResponseAt());assertEquals(20,cancelled.checkpoint().current().agenda().nowMs());}
    @Test void firstSuccessIgnoresEarlierFailureAndImpossibleAllFails(){var first=new SimulationEngineV3(groups(JoinPolicy.FIRST_SUCCESS,RemainingPolicy.CONTINUE,null,null,-10,30));first.run();assertEquals(30L,first.control().principalResponseAt());var all=new SimulationEngineV3(groups(JoinPolicy.ALL,RemainingPolicy.CONTINUE,null,null,-10,30));all.run();assertEquals("FAILURE",all.control().principalOutcome());assertEquals(10L,all.control().principalTerminalAt());assertEquals(30,all.checkpoint().current().agenda().nowMs());}
    @Test void joinDeadlineCancelsBranchesWithoutArtificialDeadlock(){var engine=new SimulationEngineV3(groups(JoinPolicy.ALL,RemainingPolicy.CANCEL_REQUEST,null,15L,20,30));engine.run();assertEquals(15L,engine.control().principalTerminalAt());assertEquals("FAILURE",engine.control().principalOutcome());assertEquals(15,engine.checkpoint().current().agenda().nowMs());assertEquals("COMPLETED",engine.control().globalStop());}
    @Test void queueAckTimeoutRedeliversAndEventuallyDeadLetters(){var engine=new SimulationEngineV3(reference(AwaitPublish.NONE,Map.of("ackTimeoutMs",n(20),"maxDeliveryAttempts",n(2),"redeliveryDelayMs",n(5))));engine.run();assertEquals(120L,engine.control().principalResponseAt());assertEquals(165,engine.checkpoint().current().agenda().nowMs());var entities=engine.checkpoint().current().state().entities().values();assertEquals(2,entities.stream().filter(e->e instanceof RuntimeEntityV3.DeliveryAttempt).count());assertTrue(entities.stream().anyMatch(e->e instanceof RuntimeEntityV3.QueueEntry q && q.status()==RuntimeEntityV3.QueueEntryStatus.DEAD_LETTERED));assertTrue(entities.stream().noneMatch(e->e instanceof RuntimeEntityV3.Lease l && l.status()==RuntimeEntityV3.LeaseStatus.HELD));}
    @Test void ttlExpiresInFlightAndAckAtExactTtlWins(){var expired=new SimulationEngineV3(reference(AwaitPublish.NONE,Map.of("ttlMs",n(50))));expired.run();assertEquals(170,expired.checkpoint().current().agenda().nowMs());assertTrue(expired.checkpoint().current().state().entities().values().stream().anyMatch(e->e instanceof RuntimeEntityV3.QueueEntry q && q.status()==RuntimeEntityV3.QueueEntryStatus.EXPIRED));var tied=new SimulationEngineV3(reference(AwaitPublish.NONE,Map.of("ttlMs",n(90))));tied.run();assertEquals(210,tied.checkpoint().current().agenda().nowMs());assertTrue(tied.checkpoint().current().state().entities().values().stream().anyMatch(e->e instanceof RuntimeEntityV3.QueueEntry q && q.status()==RuntimeEntityV3.QueueEntryStatus.ACKNOWLEDGED));}
    @Test void fullQueueRejectsWithoutChangingPrincipalForNoneMode(){var engine=new SimulationEngineV3(reference(AwaitPublish.NONE,Map.of("capacity",n(0))));engine.run();assertEquals(120L,engine.control().principalResponseAt());assertEquals(120,engine.checkpoint().current().agenda().nowMs());assertTrue(engine.checkpoint().current().state().entities().values().stream().anyMatch(e->e instanceof RuntimeEntityV3.Publication pub && pub.status()==RuntimeEntityV3.PublicationStatus.REJECTED));}
    @Test void asyncResumeAndEffectReplayAreExact(){var engine=new SimulationEngineV3(reference(AwaitPublish.NONE,Map.of()));while(engine.checkpoint().current().agenda().nowMs()<120)assertTrue(engine.step());var checkpoint=engine.checkpoint();var resumed=SimulationEngineV3.resume(checkpoint);var complete=engine.run();assertEquals(complete,resumed.run());assertEquals(complete.current(),AtomicDispatcherV3.replay(complete.initial(),complete.current().journal()));}

    @Test void branchesShareProcessingPoolFifoWithoutHoldingItAcrossJoin(){var original=groups(JoinPolicy.ALL,RemainingPolicy.CONTINUE,null,null,30,50);var a=original.architecture();var resources=new ArrayList<>(a.resources());resources.add(new Resource(id("api-pool"),id("PROCESSING_POOL"),id("api"),Map.of("capacity",n(1))));var old=a.executionPlans().getFirst();var steps=new ArrayList<Step>();for(var step:old.steps())if(step instanceof Delay d)steps.add(new Process(d.id(),d.durationMs(),id("api-pool"),next(Outcome.NEXT,d.nextStepId().value())));else steps.add(step);var plan=new ExecutionPlanV3(old.id(),old.operationId(),old.entryStepId(),old.limits(),steps);var changed=new ArchitectureV3(a.id(),a.schemaVersion(),a.components(),resources,a.endpoints(),a.operations(),a.relations(),List.of(plan));var engine=new SimulationEngineV3(new SimulationRequestV3(changed,original.scenario(),original.options()));engine.run();assertEquals(80L,engine.control().principalResponseAt());assertEquals(0L,((RuntimeEntityV3.Resource)engine.checkpoint().current().state().entities().get(id("api-pool"))).inUse());assertEquals("COMPLETED",engine.control().globalStop());}
    @Test void seededQueueMessagesAreRealGlobalWork(){var original=reference(AwaitPublish.NONE,Map.of());var old=original.scenario();var scenario=new SimulationRequestV3.Scenario(old.id(),old.entry(),List.of(new InitialStateV3.Queue(id("messages"),1L)),old.parameters());var engine=new SimulationEngineV3(new SimulationRequestV3(original.architecture(),scenario,original.options()));engine.run();assertEquals(120L,engine.control().principalResponseAt());assertEquals(210,engine.checkpoint().current().agenda().nowMs());assertEquals(180L,engine.control().processing().get(id("telemetry")));assertEquals(2,engine.checkpoint().current().state().entities().values().stream().filter(e->e instanceof RuntimeEntityV3.QueueEntry q && q.status()==RuntimeEntityV3.QueueEntryStatus.ACKNOWLEDGED).count());}
    @Test void rpcAttemptTimeoutRetriesWithoutLettingOldResponsesCompleteNewAttempt(){var original=SynchronousExecutionV3Test.fixture(null,1000L,false,true);var a=original.architecture();var resources=new ArrayList<Resource>();for(var r:a.resources())resources.add(r.id().equals(id("call-policy"))?new Resource(r.id(),r.typeId(),r.ownerId(),Map.of("attemptTimeoutMs",n(10),"maxAttempts",n(2),"retryDelayMs",n(3))):r);var changed=new ArchitectureV3(a.id(),a.schemaVersion(),a.components(),resources,a.endpoints(),a.operations(),a.relations(),a.executionPlans());var engine=new SimulationEngineV3(new SimulationRequestV3(changed,original.scenario(),original.options()));engine.run();assertEquals(63L,engine.control().principalTerminalAt());assertEquals("FAILURE",engine.control().principalOutcome());assertEquals(1,engine.checkpoint().current().trace().stream().filter(t->t.kind()==TraceRecordV3.Kind.RETRY_STARTED).count());assertTrue(engine.checkpoint().current().trace().stream().anyMatch(t->t.kind()==TraceRecordV3.Kind.RESPONSE_ARRIVED_LATE));assertTrue(engine.checkpoint().current().state().entities().values().stream().anyMatch(e->e instanceof RuntimeEntityV3.Interaction i && i.attemptIds().size()==2));}
    @Test void publicationWaitTimeoutDoesNotCancelAlreadyAcceptedConsumerWork(){var original=reference(AwaitPublish.CONSUMER_ACK,Map.of());var a=original.architecture();var resources=new ArrayList<>(a.resources());resources.add(new Resource(id("publish-policy"),id("POLICY_INSTANCE"),id("api"),Map.of("timeoutMs",n(20))));var old=a.executionPlans().getFirst();var steps=new ArrayList<Step>();for(var step:old.steps())if(step instanceof Publish pub)steps.add(new Publish(pub.id(),pub.targetResourceId(),pub.payloadProfileId(),pub.awaitMode(),id("publish-policy"),pub.transitions()));else steps.add(step);var changed=new ArchitectureV3(a.id(),a.schemaVersion(),a.components(),resources,a.endpoints(),a.operations(),a.relations(),List.of(new ExecutionPlanV3(old.id(),old.operationId(),old.entryStepId(),old.limits(),steps)));var engine=new SimulationEngineV3(new SimulationRequestV3(changed,original.scenario(),original.options()));engine.run();assertEquals(140L,engine.control().principalTerminalAt());assertEquals("FAILURE",engine.control().principalOutcome());assertEquals(210,engine.checkpoint().current().agenda().nowMs());assertTrue(engine.checkpoint().current().state().entities().values().stream().anyMatch(e->e instanceof RuntimeEntityV3.QueueEntry q && q.status()==RuntimeEntityV3.QueueEntryStatus.ACKNOWLEDGED));}

    static SimulationEngineV3 inject(SimulationEngineV3 engine,long at,DeterministicSchedulerV3.Phase phase,SimulationEventV3 payload){var cp=engine.checkpoint();var old=cp.current();var agenda=DeterministicSchedulerV3.restore(old.agenda());agenda.schedule(at,phase,payload);var changed=new AtomicDispatcherV3.Snapshot(old.executionId(),old.state(),agenda.snapshot(),old.randomState(),old.nextDispatchSequence(),old.nextTraceSequence(),old.nextDeltaSequence(),old.claims(),old.trace(),old.journal());return SimulationEngineV3.resume(new SimulationEngineV3.Checkpoint(cp.request(),old.journal().isEmpty()?changed:cp.initial(),changed));}
    @Test void duplicateRequestArrivalCannotCreateTheSameActivationTwice(){var engine=new SimulationEngineV3(SynchronousExecutionV3Test.fixture(null,null,false,true));while(engine.checkpoint().current().agenda().pending().stream().noneMatch(e->e.payload() instanceof SimulationEventV3.MessageArrivalDue))assertTrue(engine.step());var event=engine.checkpoint().current().agenda().pending().stream().filter(e->e.payload() instanceof SimulationEventV3.MessageArrivalDue).findFirst().orElseThrow();engine=inject(engine,event.scheduledAtMs(),event.phase(),event.payload());engine.run();assertEquals(95L,engine.control().principalResponseAt());assertEquals(2,engine.checkpoint().current().state().entities().values().stream().filter(e->e instanceof RuntimeEntityV3.Activation).count());assertTrue(engine.checkpoint().current().journal().stream().anyMatch(c->c.decision() instanceof DispatchDecisionV3.Ignore ignored && ignored.reason().equals("DUPLICATE_EVENT_CLAIM")));}
    @Test void nativePolicyCanBeDisabledBeforeTheCallAndFromInitialState(){var request=SynchronousExecutionV3Test.fixture(null,10L,false,true);var engine=inject(new SimulationEngineV3(request),0,DeterministicSchedulerV3.Phase.ENVIRONMENT_CHANGE,new SimulationEventV3.PolicyTransitionDue(id("call-policy"),id("disable-policy"),id("DISABLED")));engine.run();assertEquals(95L,engine.control().principalResponseAt());var old=request.scenario();var scenario=new SimulationRequestV3.Scenario(old.id(),old.entry(),List.of(new InitialStateV3.Policy(id("call-policy"),"DISABLED")),old.parameters());var initialized=new SimulationEngineV3(new SimulationRequestV3(request.architecture(),scenario,request.options()));initialized.run();assertEquals(95L,initialized.control().principalResponseAt());}
    @Test void fanoutWaitsForEveryConsumerAckAndRespectsSharedTelemetryPool(){var original=reference(AwaitPublish.CONSUMER_ACK,Map.of());var a=original.architecture();var resources=new ArrayList<Resource>();var queue=a.resources().stream().filter(r->r.id().equals(id("messages"))).findFirst().orElseThrow();for(var r:a.resources())if(r.id().equals(id("topic")))resources.add(new Resource(r.id(),r.typeId(),r.ownerId(),Map.of("queueIds",new PropertyValueV3.Values(List.of(new PropertyValueV3.Reference(id("messages"),id("MESSAGE_QUEUE")),new PropertyValueV3.Reference(id("messages-2"),id("MESSAGE_QUEUE")))))));else resources.add(r);resources.add(new Resource(id("messages-2"),queue.typeId(),queue.ownerId(),queue.properties()));var changed=new ArchitectureV3(a.id(),a.schemaVersion(),a.components(),resources,a.endpoints(),a.operations(),a.relations(),a.executionPlans());var engine=new SimulationEngineV3(new SimulationRequestV3(changed,original.scenario(),original.options()));engine.run();assertEquals(300L,engine.control().principalResponseAt());assertEquals(300,engine.checkpoint().current().agenda().nowMs());assertEquals(2,engine.checkpoint().current().state().entities().values().stream().filter(e->e instanceof RuntimeEntityV3.QueueEntry q && q.status()==RuntimeEntityV3.QueueEntryStatus.ACKNOWLEDGED).count());}
    @Test void nestedForksUseIndependentActivationsAndJoinAt25Ms(){var original=groups(JoinPolicy.ALL,RemainingPolicy.CONTINUE,null,null,20,25);var a=original.architecture();var old=a.executionPlans().getFirst();var steps=new ArrayList<Step>();for(var step:old.steps())if(step.id().equals(id("d0")))steps.add(new Fork(id("d0"),List.of(new Branch(id("nb0"),id("nd0")),new Branch(id("nb1"),id("nd1"))),id("nested-join")));else steps.add(step);steps.add(new Delay(id("nd0"),new DurationMsV3(10),id("ne0")));steps.add(new Delay(id("nd1"),new DurationMsV3(20),id("ne1")));steps.add(new Complete(id("ne0"),Scope.BRANCH,id("ok")));steps.add(new Complete(id("ne1"),Scope.BRANCH,id("ok")));steps.add(new Join(id("nested-join"),JoinPolicy.ALL,List.of(id("nb0"),id("nb1")),null,RemainingPolicy.CONTINUE,null,next(Outcome.SATISFIED,"e0")));var plan=new ExecutionPlanV3(old.id(),old.operationId(),old.entryStepId(),old.limits(),steps);var changed=new ArchitectureV3(a.id(),a.schemaVersion(),a.components(),a.resources(),a.endpoints(),a.operations(),a.relations(),List.of(plan));assertTrue(new ExecutionPlanValidatorV3(TypeCatalogV3.initial()).validate(changed,plan).valid());var engine=new SimulationEngineV3(new SimulationRequestV3(changed,original.scenario(),original.options()));engine.run();assertEquals(25L,engine.control().principalResponseAt());assertEquals("COMPLETED",engine.control().globalStop());}
    @Test void resourceWaitTimeoutFailsOneBranchAndAllowsOtherGlobalWorkToFinish(){var original=groups(JoinPolicy.ALL,RemainingPolicy.CONTINUE,null,null,30,50);var a=original.architecture();var resources=new ArrayList<>(a.resources());resources.add(new Resource(id("api-pool"),id("PROCESSING_POOL"),id("api"),Map.of("capacity",n(1),"waitTimeoutMs",n(5))));var old=a.executionPlans().getFirst();var steps=new ArrayList<Step>();for(var step:old.steps())if(step instanceof Delay d)steps.add(new Process(d.id(),d.durationMs(),id("api-pool"),next(Outcome.NEXT,d.nextStepId().value())));else steps.add(step);var changed=new ArchitectureV3(a.id(),a.schemaVersion(),a.components(),resources,a.endpoints(),a.operations(),a.relations(),List.of(new ExecutionPlanV3(old.id(),old.operationId(),old.entryStepId(),old.limits(),steps)));var engine=new SimulationEngineV3(new SimulationRequestV3(changed,original.scenario(),original.options()));engine.run();assertEquals(5L,engine.control().principalTerminalAt());assertEquals("FAILURE",engine.control().principalOutcome());assertEquals(30,engine.checkpoint().current().agenda().nowMs());assertTrue(engine.checkpoint().current().journal().stream().anyMatch(c->c.event().payload() instanceof SimulationEventV3.ResourceWaitTimeoutDue));}
}
